   156  static gboolean
   157  fu_coswid_firmware_parse_link(cbor_item_t *item, gpointer user_data, GError **error)
   158  {
   159          FuCoswidFirmware *self = FU_COSWID_FIRMWARE(user_data);
   160          FuCoswidFirmwarePrivate *priv = GET_PRIVATE(self);
   161          struct cbor_pair *pairs = cbor_map_handle(item);
   162          g_autoptr(FuCoswidFirmwareLink) link = g_new0(FuCoswidFirmwareLink, 1);
   163
   164          for (gsize i = 0; i < cbor_map_size(item); i++) {
   165                  FuCoswidTag tag_id = 0;
   166                  if (!fu_coswid_read_tag(pairs[i].key, &tag_id, error))
   167                          return FALSE;
   168                  if (tag_id == FU_COSWID_TAG_HREF) {
   169                          g_free(link->href);
   170                          link->href = fu_coswid_read_string(pairs[i].value, error);
   171                          if (link->href == NULL) {
   172                                  g_prefix_error(error, "failed to parse link href: ");
   173                                  return FALSE;
   174                          }
   175                  } else if (tag_id == FU_COSWID_TAG_REL) {
   176                          if (cbor_isa_negint(pairs[i].value)) {
   177                                  link->rel = (-1) - cbor_get_uint8(pairs[i].value);
   178                          } else if (cbor_isa_uint(item)) {
   179                                  link->rel = cbor_get_uint8(pairs[i].value);
   180                          } else {
   181                                  g_set_error_literal(
   182                                      error,
   183                                      FWUPD_ERROR,
   184                                      FWUPD_ERROR_INVALID_DATA,
   185                                      "failed to parse link rel: item is not a integer");
   186                                  return FALSE;
   187                          }
   188                  } else {
   189                          g_debug("unhandled tag %s from %s",
   190                                  fu_coswid_tag_to_string(tag_id),
   191                                  fu_coswid_tag_to_string(FU_COSWID_TAG_LINK));
   192                  }
   193          }
   194
   195          /* success */
   196          g_ptr_array_add(priv->links, g_steal_pointer(&link));
   197          return TRUE;
   198  }
